  "settings.modelProvider.help.contextWindow": "Kontextkapaciteten modellen kan bearbeta samtidigt, i tokens. ZAICODE använder detta för att hantera kontext.\nÖverskrid inte modellens faktiska gräns.",
  "settings.modelProvider.help.maxOutputTokens": "Max antal tokens en enskild modellbegäran får generera.\nÖverskrid inte modellens faktiska gräns.",
  "settings.modelProvider.help.inputModalities": "Ange innehållstyper modellen kan ta emot:\n\n- **Text**: Tar emot textinnehåll. Obligatoriskt.\n- **Bilder**: Tar emot bildinnehåll.\n- **Video**: Tar emot videoinnehåll.\n- **PDF**: Tar emot PDF-dokument direkt.",
  "settings.modelProvider.help.outputModalities": "Innehållstyp för modellens svar. Endast text stöds för närvarande.",
  "settings.modelProvider.help.capabilities": "- **Strukturerad utdata**: Stöder JSON Schema-begränsningar på utdatafält, typer och struktur.\n- **Inbyggd webbsökning**: Stöder modellens inbyggda webbsökningsfunktion.\n- **Systemmeddelanden mitt i konversationen**: Stöder infogning av systeminstruktioner under en konversation.\n\nAktivera inte funktioner modellen inte stöder.",
  "settings.modelProvider.help.reasoningLevelsOrdered": "Ange resonemangsnivåerna som är tillgängliga i chatten. **De måste ordnas från lägsta till högsta resonemangsinsats**.\nKonfigurera inte resonemangsnivåer modellen inte stöder.",
  "settings.modelProvider.help.reasoningLevelMapping": "Använd ett CEL-uttryck för att mappa den aktuella resonemangsnivån, `reasoningLevel`, till fält i modellens API-begäran. JSON-objektet som uttrycket returnerar slås ihop med den skickade begärandetexten.",
  "settings.modelProvider.help.advanced": "**MFJS-verktygsschema**: Aktiverar kompatibilitet med Moonshot Flavored JSON Schema, vanligt hos Moonshots Kimi-modell-API. Aktivera endast när modellens API kräver formatet.",
  "settings.modelProvider.help.followRecommendedConfig": "Matchar rekommenderad konfiguration utifrån modell-ID, bas-URL och API-format. ZAICODE uppdaterar rekommendationerna löpande och synkar dem automatiskt.\nNär du manuellt ändrar en inställning blir den manuellt hanterad och slutar följa rekommendationerna; övriga inställningar förblir hanterade av smart konfiguration.",
